// 1. Input Validation
if ((wp_input.wheels == NULL) || (wp_input.torque_nm == NULL) || 
    (wp_input.wheel_count != 4)) {
    wp_state.mode = WP_FAULT;
    wp_output.mode = WP_FAULT;
    wp_output.clean = 0;
    wp_output.power_limited_mask = 0;
    wp_output.slew_limited_mask = 0;
    wp_output.requested_net_power_w = 0.0;
    wp_output.delivered_net_power_w = 0.0;
    wp_output.requested_motoring_power_w = 0.0;
    wp_output.requested_regenerative_power_w = 0.0;
    wp_output.delivered_motoring_power_w = 0.0;
    wp_output.delivered_regenerative_power_w = 0.0;
    wp_output.filtered_abs_power_w = 0.0;
    wp_output.momentum_norm_nms = 0.0;
    wp_output.momentum_nms.x = 0.0; wp_output.momentum_nms.y = 0.0; wp_output.momentum_nms.z = 0.0;
    wp_output.requested_body_torque_nm.x = 0.0; wp_output.requested_body_torque_nm.y = 0.0; wp_output.requested_body_torque_nm.z = 0.0;
    wp_output.delivered_body_torque_nm.x = 0.0; wp_output.delivered_body_torque_nm.y = 0.0; wp_output.delivered_body_torque_nm.z = 0.0;
    Memsetx(wp_output.limited_torque_nm, 0, sizeof(wp_output.limited_torque_nm));
    return;
}

// Config Validation
if ((wp_config.trip_filtered_w < 0.0) || 
    (wp_config.release_filtered_w < 0.0) || 
    (wp_config.trip_filtered_w < wp_config.release_filtered_w) ||
    (wp_config.filter_alpha < 0.0) || (wp_config.filter_alpha > 1.0) ||
    (wp_config.motoring_limit_w <= 0.0) || 
    (wp_config.regenerative_limit_w <= 0.0) ||
    (wp_config.max_torque_slew_nm_per_cycle <= 0.0) ||
    (wp_config.release_cycles < 1) || (wp_config.release_cycles > 20)) {
    wp_state.mode = WP_FAULT;
    wp_output.mode = WP_FAULT;
    wp_output.clean = 0;
    wp_output.power_limited_mask = 0;
    wp_output.slew_limited_mask = 0;
    wp_output.requested_net_power_w = 0.0;
    wp_output.delivered_net_power_w = 0.0;
    wp_output.requested_motoring_power_w = 0.0;
    wp_output.requested_regenerative_power_w = 0.0;
    wp_output.delivered_motoring_power_w = 0.0;
    wp_output.delivered_regenerative_power_w = 0.0;
    wp_output.filtered_abs_power_w = 0.0;
    wp_output.momentum_norm_nms = 0.0;
    wp_output.momentum_nms.x = 0.0; wp_output.momentum_nms.y = 0.0; wp_output.momentum_nms.z = 0.0;
    wp_output.requested_body_torque_nm.x = 0.0; wp_output.requested_body_torque_nm.y = 0.0; wp_output.requested_body_torque_nm.z = 0.0;
    wp_output.delivered_body_torque_nm.x = 0.0; wp_output.delivered_body_torque_nm.y = 0.0; wp_output.delivered_body_torque_nm.z = 0.0;
    Memsetx(wp_output.limited_torque_nm, 0, sizeof(wp_output.limited_torque_nm));
    return;
}

adcs_vec3_t momentum_nms = {0};
double req_motoring_p = 0.0;
double req_regenerative_p = 0.0;
double req_net_p = 0.0;
double req_torques[4];
double scaled_torques[4];
unint32 power_limited_mask = 0;

// 2. Calculate Requested Powers
for (int i = 0; i < 4; ++i) {
    req_torques[i] = wp_input.torque_nm[i];
    double p = req_torques[i] * wp_input.wheels[i].speed_rad_s;
    if (p > 0.0) req_motoring_p += p;
    else if (p < 0.0) req_regenerative_p += (-p);
}
req_net_p = req_motoring_p - req_regenerative_p;

// 3. Power Limiting & Scaling
for(int i=0; i<4; ++i) scaled_torques[i] = req_torques[i];

if (req_motoring_p > wp_config.motoring_limit_w) {
    double scale = wp_config.motoring_limit_w / req_motoring_p;
    for (int i = 0; i < 4; ++i) {
        if (req_torques[i] * wp_input.wheels[i].speed_rad_s > 0.0) {
            scaled_torques[i] *= scale;
            power_limited_mask |= (1U << i);
        }
    }
}

if (req_regenerative_p > wp_config.regenerative_limit_w) {
    double scale = wp_config.regenerative_limit_w / req_regenerative_p;
    for (int i = 0; i < 4; ++i) {
        if (req_torques[i] * wp_input.wheels[i].speed_rad_s < 0.0) {
            scaled_torques[i] *= scale;
            power_limited_mask |= (1U << i);
        }
    }
}

// 4. Slew Limiting
unint32 slew_limited_mask = 0;
double delivered_torques[4];
double max_slew = wp_config.max_torque_slew_nm_per_cycle;

for (int i = 0; i < 4; ++i) {
    double prev = wp_state.previous_torque_nm[i];
    double min_t = prev - max_slew;
    double max_t = prev + max_slew;
    double s_t = scaled_torques[i];

    if (s_t < min_t) {
        delivered_torques[i] = min_t;
        slew_limited_mask |= (1U << i);
    } else if (s_t > max_t) {
        delivered_torques[i] = max_t;
        slew_limited_mask |= (1U << i);
    } else {
        delivered_torques[i] = s_t;
    }
}

// 5. Calculate Delivered Powers
double del_motoring_p = 0.0;
double del_regenerative_p = 0.0;
for (int i = 0; i < 4; ++i) {
    double p = delivered_torques[i] * wp_input.wheels[i].speed_rad_s;
    if (p > 0.0) del_motoring_p += p;
    else if (p < 0.0) del_regenerative_p += (-p);
}
double del_net_p = del_motoring_p - del_regenerative_p;

// 6. Filtered Power
double abs_req_net = fabs(req_net_p);
double filtered_abs_power = wp_config.filter_alpha * abs_req_net + 
                            (1.0 - wp_config.filter_alpha) * wp_state.filtered_abs_power_w;

// 7. State Machine
int any_power_limited = (power_limited_mask != 0);
int any_slew_limited = (slew_limited_mask != 0);
int trip_triggered = (filtered_abs_power >= wp_config.trip_filtered_w);

if (any_power_limited || any_slew_limited || trip_triggered) {
    wp_state.mode = WP_LIMITED;
    wp_state.clean = 0;
} else {
    if (wp_state.mode == WP_RECOVERING) {
        wp_state.clean++;
        if (wp_state.clean >= wp_config.release_cycles) {
            wp_state.mode = WP_NORMAL;
            wp_state.clean = 0;
        }
    } else if (wp_state.mode == WP_LIMITED) {
        wp_state.mode = WP_RECOVERING;
        wp_state.clean = 1;
    } else {
        wp_state.clean = 0;
    }
}

wp_state.filtered_abs_power_w = filtered_abs_power;
for(int i=0; i<4; ++i) wp_state.previous_torque_nm[i] = delivered_torques[i];

// 8. Momentum and Body Torque
adcs_wheel_momentum(wp_input.wheels, 4, &momentum_nms);

adcs_vec3_t req_body_torque = {0};
adcs_vec3_t del_body_torque = {0};

for (int i = 0; i < 4; ++i) {
    req_body_torque = adcs_vec3_add(&req_body_torque, &adcs_vec3_scale(&wp_input.wheels[i].axis_body, req_torques[i]));
    del_body_torque = adcs_vec3_add(&del_body_torque, &adcs_vec3_scale(&wp_input.wheels[i].axis_body, delivered_torques[i]));
}

adcs_vec3_t req_reaction = adcs_vec3_scale(&req_body_torque, -1.0);
adcs_vec3_t del_reaction = adcs_vec3_scale(&del_body_torque, -1.0);

// 9. Populate Output
wp_output.mode = wp_state.mode;
wp_output.clean = wp_state.clean;
wp_output.power_limited_mask = power_limited_mask;
wp_output.slew_limited_mask = slew_limited_mask;
wp_output.requested_net_power_w = req_net_p;
wp_output.delivered_net_power_w = del_net_p;
wp_output.requested_motoring_power_w = req_motoring_p;
wp_output.requested_regenerative_power_w = req_regenerative_p;
wp_output.delivered_motoring_power_w = del_motoring_p;
wp_output.delivered_regenerative_power_w = del_regenerative_p;
wp_output.filtered_abs_power_w = filtered_abs_power;
wp_output.momentum_nms = momentum_nms;
wp_output.momentum_norm_nms = adcs_vec3_norm(&momentum_nms);
wp_output.requested_body_torque_nm = req_reaction;
wp_output.delivered_body_torque_nm = del_reaction;
Memcpyx(wp_output.limited_torque_nm, delivered_torques, sizeof(delivered_torques));

